 package s2

+import "fmt"
+
 // Shape interface enforcement
 var _ Shape = (*LaxPolygon)(nil)

@@ -220,5 +222,60 @@ func (p *LaxPolygon) ChainPosition(e int) ChainPosition {
 	return ChainPosition{p.cumulativeVertices[nextLoop] - p.cumulativeVertices[1], e - p.cumulativeVertices[nextLoop-1]}
 }

+func (p *LaxPolygon) encode(e *encoder) {
+	e.writeInt8(encodingVersion)
+	e.writeUint32(uint32(p.numLoops))
+	for i := 0; i < p.numLoops; i++ {
+		e.writeUint32(uint32(p.numLoopVertices(i)))
+	}
+	for _, v := range p.vertices {
+		e.writeFloat64(v.X)
+		e.writeFloat64(v.Y)
+		e.writeFloat64(v.Z)
+	}
+}
+
+func (p *LaxPolygon) decode(d *decoder) {
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("cannot decode version %d", version)
+		return
+	}
+	nloops := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if nloops > maxEncodedLoops {
+		d.err = fmt.Errorf("too many loops (%d; max is %d)", nloops, maxEncodedLoops)
+		return
+	}
+	loops := make([][]Point, nloops)
+	for i := range loops {
+		nv := d.readUint32()
+		if d.err != nil {
+			return
+		}
+		if nv > maxEncodedVertices {
+			d.err = fmt.Errorf("too many vertices (%d; max is %d)", nv, maxEncodedVertices)
+			return
+		}
+		loops[i] = make([]Point, nv)
+	}
+	for i := range loops {
+		for j := range loops[i] {
+			loops[i][j].X = d.readFloat64()
+			loops[i][j].Y = d.readFloat64()
+			loops[i][j].Z = d.readFloat64()
+		}
+	}
+	if d.err != nil {
+		return
+	}
+	*p = *LaxPolygonFromPoints(loops)
+}
+
